create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_CORE.T_LOCATION_HIST_1 (
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'unique identifier of the DWH client / slice',
	LOC_SID NUMBER(38,0) NOT NULL COMMENT 'Surrogate Key LOCATION_1',
	LOC_TYPE_CD VARCHAR(2) COLLATE 'en-ci' COMMENT 'Code for the discriminator values for locations. (store vs. warehouse)',
	LOC_NR VARCHAR(20) COLLATE 'en-ci' COMMENT 'The number by which the store or warehouse is known to business.',
	LOC_NAME VARCHAR(100) COLLATE 'en-ci' COMMENT 'name of the Organization/WH/Store (w/i Retail-System); SAP-Retail: t001w.name1; SAP-BW: t_bw_0plant_attr.name1',
	LOC_STATUS_CD VARCHAR(5) COLLATE 'en-ci' COMMENT 'A code for the status_1 of a location. (active, closed, ...)',
	WH_ACTIVE_FG NUMBER(38,0) COMMENT 'indicating, whether Warehouse is active',
	CLOSED_FG NUMBER(38,0) COMMENT 'An indicator showing, whether the store is closed.',
	TEST_STORE_FG NUMBER(38,0) COMMENT 'indicating, whether Store is a Test_1 Store',
	DUMMY_STORE_FG NUMBER(38,0) COMMENT 'An indicator showing, if this store is classified as a dummy_1 store. (Dummy_1 stores are created either by the source or the load process and represent warehouses and countries. So ultimately, they should not be present in this table.)',
	TEMPLATE_STORE_FG NUMBER(38,0) COMMENT 'An indicator showing, if this store is used as a template for new stores.',
	SALES_WH_FG NUMBER(38,0) COMMENT 'WH is Sales_1 WH (\""Vertriebsgesellschaft (VGES)\""); IMS_ESB: associations.association.is-sal (Vertriebsgesellschaft (VGES))',
	DELIVERY_WH_FG NUMBER(38,0) COMMENT 'WH is Delivery WH (\""beliefernde Gesellschaft (BGES)\""); IMS_ESB: associations.association.is-del (beliefernde Gesellschaft (BGES))',
	EXPANSION_WH_FG NUMBER(38,0) COMMENT 'WH is Expansion WH (\""Expansionsgesellschaft\""); IMS_ESB: associations.association.is-exp (Expansionsgesellschaft)',
	BALANCE_SHEET_WH_FG NUMBER(38,0) COMMENT 'WH is Balance Sheet WH (\""Bilanzgesellschaft\""); IMS_ESB: associations.association.is-bal (Bilanzgesellschaft)',
	OWNER_WH_FG NUMBER(38,0) COMMENT 'WH is Owner WH (\""Eigentumsgesellschaft\""); IMS_ESB: associations.association.is-owner (Eigentumsgesellschaft)',
	COUNTRY_WH_FG NUMBER(38,0) COMMENT 'WH is Country_1 WH (\""Landesdienstleistung\""); IMS_ESB: associations.association.is-cty (Landesdienstleistung)',
	OPENING_DT DATE COMMENT 'Opening-Date (Retail perspective); SAP-Retail: wrf1.eroed; SAP-BW: 0rt_wrf1_attr.eroed;',
	REAL_OPENING_DT DATE COMMENT 'The actual opening date. (This might be different from the planned opening date.)',
	CLOSING_DT DATE COMMENT 'Closing-Date (Retail perspective); SAP-Retail: wrf1.schld; SAP-BW: 0rt_wrf1_attr.schld; ELWIS: t_s_loc_wrf1.close_dat',
	ADDR_SID NUMBER(38,0) COMMENT 'address_1 of the Warehouse/Store;',
	GLOBAL_LOCATION_NR VARCHAR(13) COLLATE 'en-ci' COMMENT 'A 13-digit number identifying a geographical location_1 or a legal entity. A global location_1 number (GLN) consists of a company prefix, a location_1 identifier and a check digit.',
	LEGAL_ENTITY_NAME VARCHAR(100) COLLATE 'en-ci' COMMENT 'The official company name of this organizatation.',
	VAT_IDENT_NR VARCHAR(20) COLLATE 'en-ci' COMMENT 'The VAT identification number of the warehouse. (Umsatzsteuer-Identifikationsnummer)',
	LOC_SID_SALES_WH NUMBER(38,0) COMMENT 'assigned Sales_1 WH for the Store; IMS_ESB: loc_sid associated with the t_location.assoc_id (IMS_ESB: associations.association.id)',
	LOC_SID_DELIVERY_WH NUMBER(38,0) COMMENT 'assigned Delivery WH for the Store; IMS_ESB: loc_sid associated with the t_location.assoc_id (IMS_ESB: associations.association.id)',
	LOC_SID_EXPANSION_WH NUMBER(38,0) COMMENT 'assigned Expansion WH for the Store; IMS_ESB: loc_sid associated with the t_location.assoc_id (IMS_ESB: associations.association.id)',
	LOC_SID_BALANCE_SHEET_WH NUMBER(38,0) COMMENT 'assigned Balance Sheet WH for the Store; IMS_ESB: loc_sid associated with the t_location.assoc_id (IMS_ESB: associations.association.id)',
	LOC_SID_OWNER_WH NUMBER(38,0) COMMENT 'assigned Owner WH for the Store; IMS_ESB: IMS_ESB: loc_sid associated with the t_location.assoc_id (IMS_ESB: associations.association.id)',
	LOC_SID_COUNTRY_WH NUMBER(38,0) COMMENT 'assigned Country_1 WH for the Store; IMS_ESB: loc_sid associated with the t_location.assoc_id (IMS_ESB: associations.association.id)',
	LOC_SID_SUCCESSOR NUMBER(38,0) COMMENT 'the succeeding Store/Warehouse, after the Store/Warehouse is closed',
	COST_CENTER_NR VARCHAR(20) COLLATE 'en-ci' COMMENT 'The number of the cost center which is associated to this warehouse.',
	STORE_LANG_CD VARCHAR(2) COLLATE 'en-ci' COMMENT 'The ISO code of the language that is used in this store.',
	DEFAULT_ORDER_UNIT_FG NUMBER(38,0) COMMENT 'Default Order Unit_1 is valid for this Store; T008_Store.C008_ORD_UNIT_DFLT',
	DEFAULT_MIN_ORDER_UNIT_FG NUMBER(38,0) COMMENT 'globally defined minimum order quantity is valid for this Store; T008_STORE.C008_MIN_QTY_DFLT',
	ORDER_BUYING_LIST_SEQ NUMBER(38,0) COMMENT 'sort order on the buying list; Wawi source field: T010_Warehouse.C010_Order_EKList',
	SALES_ORG_SID NUMBER(38,0) COMMENT '(deprecated) Verkaufsorganisation fur interne Verrechnung; FK auf SALES_1 ORG; SAP-Retail: t001w.VKORG',
	PUR_ORG_SID NUMBER(38,0) COMMENT '(deprecated) Einkaufsorganisation; FK auf PURCHASE ORG; SAP-Retail: t001w.EKORG',
	BUS_CAL_CD VARCHAR(20) COMMENT '(deprecated) Logistikkalenderschlussel; SAP-Retail: t001w.FABKL; Zielentitat noch nicht vorhanden',
	CUSTOMER_DISTRICT_CD VARCHAR(20) COMMENT '(deprecated) Kundenbezirk; SAP-Retail: t001w.BZIRK ',
	REGION_CD VARCHAR(20) COMMENT '(deprecated) Region_1 (Bundesstaat, Bundesland, Provinz, Grafschaft); SAP-Retail: t001w.REGIO',
	ARCHIVE_FG NUMBER(38,0) COMMENT '(deprecated) Zentrale Archivierungsvormerkung fur Stammsatz; SAP-Retail: t001w.ACHVM',
	DEMAND_PLAN_ACTIVE_FG NUMBER(38,0) COMMENT '(deprecated) Aktivierung der Bedarfsplanung; SAP-Retail: t001w.BEDPL',
	DISTRIBUTION_CHANNEL_CD VARCHAR(20) COMMENT '(deprecated) Vertriebsweg fur interne Verrechnung; SAP-Retail: t001w.VTWEG; ELWIS: sales_chn_id',
	ASSESSMENT_AREA_CD VARCHAR(20) COMMENT '(deprecated) Bewertungskreis; SAP-Retail: t001w.BWKEY; ELWIS: ases_area_id',
	DIVISION_CD VARCHAR(20) COMMENT '(deprecated) Sparte fur interne Verrechnung; SAP-Retail: t001w.SPART; ELWIS: div_cd',
	MON_OPENING_TM TIME(0) COMMENT 'The time when the stores opens on Mondays. E.g. 08:00; Time is in local time.',
	MON_CLOSING_TM TIME(0) COMMENT 'The time when the stores closes on Mondays. E.g. 20:00; Time is in local time. In case the store is closed during lunch time, this is the final closing time in the evening.',
	MON_BREAK_START_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the begin time of the break for a Monday.',
	MON_BREAK_END_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the end time of the break for a Monday.',
	TUE_OPENING_TM TIME(0) COMMENT 'The time when the stores opens on Tuesdays. E.g. 08:00; Time is in local time.',
	TUE_CLOSING_TM TIME(0) COMMENT 'The time when the stores closes on Tuesdays. E.g. 20:00; Time is in local time. In case the store is closed during lunch time, this is the final closing time in the evening.',
	TUE_BREAK_START_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the begin time of the break for a Tuesday.',
	TUE_BREAK_END_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the end time of the break for a Tuesday.',
	WED_OPENING_TM TIME(0) COMMENT 'The time when the stores opens on Wednesdays. E.g. 08:00; Time is in local time.',
	WED_CLOSING_TM TIME(0) COMMENT 'The time when the stores closes on Wednesdays. E.g. 20:00; Time is in local time. In case the store is closed during lunch time, this is the final closing time in the evening.',
	WED_BREAK_START_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the begin time of the break for a Wednesday.',
	WED_BREAK_END_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the end time of the break for a Wednesday.',
	THU_OPENING_TM TIME(0) COMMENT 'The time when the stores opens on Thursdays. E.g. 08:00; Time is in local time.',
	THU_CLOSING_TM TIME(0) COMMENT 'The time when the stores closes on Thursdays. E.g. 20:00; Time is in local time. In case the store is closed during lunch time, this is the final closing time in the evening.',
	THU_BREAK_START_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the begin time of the break for a Thursday.',
	THU_BREAK_END_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the end time of the break for a Thursday.',
	FRI_OPENING_TM TIME(0) COMMENT 'The time when the stores opens on Fridays. E.g. 08:00; Time is in local time.',
	FRI_CLOSING_TM TIME(0) COMMENT 'The time when the stores closes on Fridays. E.g. 20:00; Time is in local time. In case the store is closed during lunch time, this is the final closing time in the evening.',
	FRI_BREAK_START_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the begin time of the break for a Friday.',
	FRI_BREAK_END_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the end time of the break for a Friday.',
	SAT_OPENING_TM TIME(0) COMMENT 'The time when the stores opens on Saturdays. E.g. 08:00; Time is in local time.',
	SAT_CLOSING_TM TIME(0) COMMENT 'The time when the stores closes on Saturdays. E.g. 20:00; Time is in local time. In case the store is closed during lunch time, this is the final closing time in the evening.',
	SAT_BREAK_START_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the begin time of the break for a Saturday.',
	SAT_BREAK_END_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the end time of the break for a Saturday.',
	SUN_OPENING_TM TIME(0) COMMENT 'The time when the stores opens on Sundays. E.g. 08:00; Time is in local time.',
	SUN_CLOSING_TM TIME(0) COMMENT 'The time when the stores closes on Sundays. E.g. 20:00; Time is in local time. In case the store is closed during lunch time, this is the final closing time in the evening.',
	SUN_BREAK_START_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the begin time of the break for a Sunday.',
	SUN_BREAK_END_TM TIME(0) COMMENT 'In case the store is closed for lunch break / siesta - this is the end time of the break for a Sunday.',
	OPEN_ON_HOLIDAYS_FG NUMBER(38,0) COMMENT 'An indicator showing, if the store is open on public holidays.',
	OPENING_HOURS_PER_WEEK_CNT NUMBER(9,5) COMMENT 'The total number of hours the store is open per week.',
	OPENING_HOURS_TXT VARCHAR(1000) COLLATE 'en-ci' COMMENT 'A textual description of the opening hours of the store for each weekday. \n            E.g.: Monday: 08:00 - 21:00, Tuesday: 08:00:21:00, ...',
	DELETED_FG NUMBER(38,0) NOT NULL COMMENT 'attribute set was not delivered by source system (anymore), if deleted_fg=1',
	DWH_VALID_FROM DATE NOT NULL COMMENT 'Begin of the validity_1 interval of the record, oldest record of the history starts with 1900-01-01 (minus infinity).',
	DWH_VALID_TO DATE NOT NULL COMMENT 'End of the validity_1 interval of the record, newest record of the history ends with 9999-12-30 (plus infinity).',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Identifier of the last run which inserted or updated the record. -1 means manually inserted.',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Creation timestamp of the record in the DWH.',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Timestamp of the last update of the record in the DWH.',
	constraint PK_T_LOCATION_HIST primary key (LOC_SID, DWH_VALID_FROM)
)COMMENT='$Revision: 0000 $. Stores and Warehouses (Organizational View - not the physical buildings)\n             Warehouses may represent Sales_1 Org. (VGES), Delivery Org. (BGES), Expansion Org., Owner Org., Balance Sheet Org., Country_1 Org'
